// server.js — no boot validation, no heap sizing
import express from 'express';

const app = express();
app.get('/users/:id', async (req, res) => {
  // ❌ DATABASE_URL read lazily; if unset, this 500s at 3am
  const db = connect(process.env.DATABASE_URL);
  res.json(await db.user(req.params.id));
});

// ❌ no --max-old-space-size: heap can drift past the 512 MB cgroup → OOMKill 137
app.listen(Number(process.env.PORT) || 3000);

model.en:
Validate at boot with a schema, freeze the result, and size the heap to the container in NODE_OPTIONS:

// config.js
import { z } from 'zod';
const Schema = z.object({
  NODE_ENV: z.enum(['development','test','production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000),
  DATABASE_URL: z.string().url(),            // required, no default
});
const parsed = Schema.safeParse(process.env);
if (!parsed.success) {
  console.error('invalid config:\n' + z.prettifyError(parsed.error));
  process.exit(1);                            // crash at boot, deploy goes red
}
export const config = Object.freeze(parsed.data);

// server.js
import { config } from './config.js';
const db = connect(config.databaseUrl);       // read once, typed, frozen
app.listen(config.port);

# heap sizing — 512 MB limit → ~75% = 384, headroom for buffers/native/stacks
# put it in NODE_OPTIONS so it reaches worker threads and forked children too
ENV NODE_OPTIONS="--max-old-space-size=384"

Why it's right: a missing/malformed DATABASE_URL now fails safeParse and exits 1 at boot — the canary never takes traffic, so the 3am 500 class is gone. config is read once into a frozen typed object (no scattered process.env reads, no runtime mutation). And --max-old-space-size=384 puts V8's heap ceiling under the 512 MB cgroup, so V8 GCs hard and throws a clean OOM instead of being SIGKILLed at 137; NODE_OPTIONS propagates the flag to child node processes.

model.ru:
Проверь при старте схемой, заморозь результат и задай размер кучи под контейнер в NODE_OPTIONS:

// config.js
import { z } from 'zod';
const Schema = z.object({
  NODE_ENV: z.enum(['development','test','production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000),
  DATABASE_URL: z.string().url(),            // required, no default
});
const parsed = Schema.safeParse(process.env);
if (!parsed.success) {
  console.error('invalid config:\n' + z.prettifyError(parsed.error));
  process.exit(1);                            // crash at boot, deploy goes red
}
export const config = Object.freeze(parsed.data);

// server.js
import { config } from './config.js';
const db = connect(config.databaseUrl);       // read once, typed, frozen
app.listen(config.port);

# heap sizing — лимит 512 МБ → ~75% = 384, запас под buffers/native/stacks
# клади в NODE_OPTIONS, чтобы флаг достигал и worker-потоков, и форкнутых детей
ENV NODE_OPTIONS="--max-old-space-size=384"

Почему верно: отсутствующая/некорректная DATABASE_URL теперь валит safeParse и выходит с 1 при старте — канарейка никогда не берёт трафик, так что класс 500 в 3 ночи исчез. config читается один раз в замороженный типизированный объект (без разбросанных чтений process.env, без мутации в рантайме). А --max-old-space-size=384 ставит потолок кучи V8 ниже cgroup на 512 МБ, так что V8 жёстко делает GC и бросает чистый OOM вместо SIGKILL на 137; NODE_OPTIONS протаскивает флаг в дочерние node-процессы.
